import { useState, useRef, useEffect } from "react";

// ═══════════════════════════════════════════════════════════
// SERAI / SCANNER
// Old-Money Tennis Club + Real Nature Photography
// ═══════════════════════════════════════════════════════════
const COLORS = {
  racingGreen: "#1F3D2E",
  racingGreenDeep: "#152A20",
  racingGreenSoft: "#2A4D3A",
  cream: "#F4EFE0",
  creamSoft: "#EBE4D0",
  navy: "#1A2841",
  navyDeep: "#101A30",
  brick: "#C66B3D",
  brickDeep: "#A8552C",
  tan: "#B8956A",
  sage: "#A8B89A",
};

// Atmospheric garden / hedge photography — works for both green and navy modes
const BG_IMAGE = "data:image/jpeg;base64,";

const SYSTEM_PROMPT = `You are SERAI / SCANNER — a beauty product reality check tool for the Indian market.

INPUT: User gives either (a) photo of a product label, OR (b) pasted ingredient list.
If image: extract ingredients first, then analyse.
If text: analyse directly.

OUTPUT: JSON ONLY. No markdown, no backticks, no preamble.

═══ SCHEMA ═══
{
  "extractedIngredients": "comma-separated list (only if image provided, else empty string)",
  "score": number 0-10, one decimal allowed,
  "statusTag": "ONE of: SOVEREIGN GRADE | FOREST SAFE | GREEN FLAG | ACTUALLY GOOD | SAFE-ISH | MID FORMULA | SENSITIVE-SKIN SAFE-ISH | QUESTIONABLE | MARKETING DRAMA | OVERPERFUMED | LAB DRAMA | RED FLAG FORMULA",
  "punchline": "ONE editorial line, max 10 words",
  "keepSkip": "ONE of: KEEPER | ROTATIONAL | OCCASIONAL USE | PROCEED CAREFULLY | SKIP",
  "meters": {
    "skinSafety": {"barrierStress":"LOW|MID|HIGH","irritationRisk":"LOW|MID|HIGH","acneTrigger":"LOW|MID|HIGH","activesBalance":"LOW|MID|HIGH"},
    "honesty": {"botanicalReality":"e.g. '4%'","marketingVsFormula":"LOW|MID|HIGH","fragranceLoad":"LOW|MID|HIGH"},
    "practical": {"humidityCompatibility":"YES|NO|MIXED","melaninMatch":"SAFE|CAUTION|AVOID","valueVsPricing":"LOW|MID|HIGH"}
  },
  "redFlags": [{"ingredient":"name","concern":"1 sentence plain English"}],
  "cleanIngredients": ["array"],
  "bottomLine": "2-3 sentences, friend-to-friend tone"
}

═══ STATUS TAG → SCORE ═══
SOVEREIGN GRADE: 9.5-10 — RESERVED FOR SERAI ONLY. Never assign.
FOREST SAFE: 8.5-9.4 | GREEN FLAG: 7.5-8.4 | ACTUALLY GOOD: 7.0-7.4
SAFE-ISH: 6.0-6.9 | SENSITIVE-SKIN SAFE-ISH: modifier | MID FORMULA: 5.0-5.9
QUESTIONABLE: 4.0-4.9 | MARKETING DRAMA: 3.5-4.5 | OVERPERFUMED: 3.0-4.0
LAB DRAMA: 2.0-3.5 | RED FLAG FORMULA: 0-2.5

═══ 8 TONAL RULES ═══
1. Max 10 words 2. Observational not moralising 3. Match spice to verdict
4. Genuinely positive when warranted (1 in 4) 5. No medical claims
6. No competitor names 7. No body shaming 8. Indian-fluent but globally readable

═══ REFERENCE PUNCHLINES ═══
"Hydration queen. Fragrance villain."
"Good formula trapped in bad marketing."
"The herbs are in the marketing, not the formula."
"More leaves on the packaging than in the bottle."
"Luxury packaging. Mid formulation."
"Actually decent." | "Surprisingly disciplined." | "Your barrier deserves better."
"Trying too hard." | "All cologne, no character." | "Honestly? Pretty solid."

═══ APPROACH ═══
Don't over-flag. Reward clean formulas. Evidence-backed concerns only.
Plain English over chemistry. Indian market context matters.`;

const TAG_META = {
  "SOVEREIGN GRADE": { tier: "top" }, "FOREST SAFE": { tier: "top" },
  "GREEN FLAG": { tier: "top" }, "ACTUALLY GOOD": { tier: "top" },
  "SAFE-ISH": { tier: "mid" }, "MID FORMULA": { tier: "mid" },
  "SENSITIVE-SKIN SAFE-ISH": { tier: "mid" },
  "QUESTIONABLE": { tier: "low" }, "MARKETING DRAMA": { tier: "low" },
  "OVERPERFUMED": { tier: "low" }, "LAB DRAMA": { tier: "low" },
  "RED FLAG FORMULA": { tier: "low" },
};

const KEEP_META = {
  "KEEPER": { tier: "top" }, "ROTATIONAL": { tier: "top" },
  "OCCASIONAL USE": { tier: "mid" },
  "PROCEED CAREFULLY": { tier: "low" }, "SKIP": { tier: "low" },
};

const isRiskHigh = (key, value) => {
  if (["barrierStress","irritationRisk","acneTrigger","activesBalance","marketingVsFormula","fragranceLoad"].includes(key)) {
    return value === "HIGH";
  }
  return false;
};

export default function App() {
  const [theme, setTheme] = useState("green");
  const [stage, setStage] = useState("scan");
  const [mode, setMode] = useState("photo");
  const [ingredients, setIngredients] = useState("");
  const [image, setImage] = useState(null);
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [loadingMsg, setLoadingMsg] = useState("");
  const [error, setError] = useState("");
  const [activeTab, setActiveTab] = useState("breakdown");
  const [email, setEmail] = useState("");
  const [emailError, setEmailError] = useState("");
  const [mounted, setMounted] = useState(false);
  const fileInputRef = useRef(null);

  useEffect(() => { setTimeout(() => setMounted(true), 60); }, []);

  const isNavy = theme === "navy";
  const BG       = isNavy ? COLORS.navy : COLORS.racingGreen;
  const BG_DEEP  = isNavy ? COLORS.navyDeep : COLORS.racingGreenDeep;
  const SURFACE  = "rgba(244,239,224,0.06)";
  const SURFACE_SOLID = isNavy ? "rgba(26,40,65,0.85)" : "rgba(31,61,46,0.85)";
  const INK      = COLORS.cream;
  const INK_SOFT = "rgba(244,239,224,0.75)";
  const INK_FAINT= "rgba(244,239,224,0.5)";
  const LINE     = "rgba(244,239,224,0.18)";
  const LINE_BOLD= "rgba(244,239,224,0.35)";
  const ACCENT   = COLORS.brick;
  const ACCENT_2 = COLORS.tan;

  const tierColor = (tier) => {
    if (tier === "top") return INK;
    if (tier === "mid") return ACCENT_2;
    return ACCENT;
  };

  const handleImageUpload = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      const dataUrl = ev.target.result;
      setImage({ base64: dataUrl.split(",")[1], mediaType: file.type, previewUrl: dataUrl });
      setError("");
    };
    reader.readAsDataURL(file);
  };

  const startAnalysis = () => {
    if (mode === "photo" && !image) return;
    if (mode === "text" && !ingredients.trim()) return;
    setStage("gate");
  };

  const submitEmail = () => {
    if (!email.trim()) { setEmailError("Drop an email or skip"); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { setEmailError("Doesn't look right"); return; }
    setEmailError("");
    runAnalysis();
  };

  const skipEmail = () => runAnalysis();

  const runAnalysis = async () => {
    setLoading(true); setError(""); setResult(null);
    try {
      let content;
      if (mode === "photo" && image) {
        setLoadingMsg("Reading the label");
        const mediaType =

  image.mediaType === "image/avif"

    ? "image/jpeg"

    : image.mediaType;
    content = [
          { type: "image", source: { type: "base64", media_type: mediaType, data: image.base64 } },
          { type: "text", text: "Photo of a beauty/personal care product label. Extract ingredients then run SERAI/SCANNER analysis." },
        ];
      } else {
        setLoadingMsg("Decoding the formula");
        content = `Run SERAI/SCANNER analysis on these ingredients:\n\n${ingredients}`;
      }

      const WORKER_URL = import.meta.env.VITE_WORKER_URL || "/api/scan";
      const res = await fetch(WORKER_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-5",
          max_tokens: 1500,
          system: SYSTEM_PROMPT,
          messages: [{ role: "user", content }],
        }),
      });

      const data = await res.json();
      const raw = data.content?.[0]?.text || "";
      const parsed = JSON.parse(raw.replace(/```json|```/g, "").trim());
      setResult(parsed);
      setActiveTab("breakdown");
      setStage("result");
    } catch {
      setError("Couldn't read this. Bright light, close shot, ingredients in focus.");
      setStage("scan");
    } finally {
      setLoading(false); setLoadingMsg("");
    }
  };

  const reset = () => {
    setResult(null); setImage(null); setIngredients("");
    setError(""); setEmail(""); setEmailError("");
    setStage("scan");
  };

  const tagMeta = result ? (TAG_META[result.statusTag] || { tier: "mid" }) : null;
  const tagColor = tagMeta ? tierColor(tagMeta.tier) : INK;
  const keepMeta = result ? (KEEP_META[result.keepSkip] || { tier: "mid" }) : null;
  const keepColor = keepMeta ? tierColor(keepMeta.tier) : INK;

  // The Wordmark — reusable component
  const Wordmark = ({ size = "lg" }) => {
    const SERAI_SIZE = size === "lg" ? 36 : size === "md" ? 26 : 20;
    const SERAI_SPACE = size === "lg" ? 10 : size === "md" ? 7 : 5;
    const SCRIPT_SIZE = size === "lg" ? 54 : size === "md" ? 40 : 32;
    const SCRIPT_LEFT = size === "lg" ? 14 : size === "md" ? 10 : 8;

    return (
      <div style={{ display: "inline-flex", alignItems: "center", lineHeight: 1 }}>
        <span style={{
          fontFamily: "'Libre Caslon Display', 'Libre Caslon Text', serif",
          fontSize: SERAI_SIZE,
          fontWeight: 400,
          letterSpacing: SERAI_SPACE,
          color: INK,
          textTransform: "uppercase",
          lineHeight: 1,
        }}>
          Serai
        </span>
        <span style={{
          fontFamily: "'Italianno', cursive",
          fontSize: SCRIPT_SIZE,
          fontWeight: 400,
          color: ACCENT,
          marginLeft: SCRIPT_LEFT,
          lineHeight: 1,
          display: "inline-block",
          position: "relative",
          top: size === "lg" ? "0.12em" : "0.1em",
        }}>
          Scanner
        </span>
      </div>
    );
  };

  return (
    <div style={{
      minHeight: "100vh",
      background: BG,
      color: INK,
      fontFamily: "'DM Sans', sans-serif",
      transition: "background 0.5s ease",
      position: "relative",
      overflow: "hidden",
    }}>

      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Libre+Caslon+Display&family=Libre+Caslon+Text:ital,wght@0,400;0,700;1,400&family=Italianno&family=DM+Sans:wght@300;400;500;600;700&display=swap');

        * { box-sizing: border-box; margin: 0; padding: 0; -webkit-font-smoothing: antialiased; }

        .serai-btn {
          width: 100%; padding: 18px 24px; border: none;
          background: ${COLORS.brick}; color: ${COLORS.cream}; cursor: pointer;
          font-family: 'DM Sans', sans-serif; font-size: 12px;
          letter-spacing: 3.5px; font-weight: 700;
          transition: all 0.3s ease; text-transform: uppercase;
        }
        .serai-btn:hover:not(:disabled) {
          background: ${COLORS.brickDeep}; letter-spacing: 4.5px;
        }
        .serai-btn:disabled { opacity: 0.3; cursor: not-allowed; }

        .ghost-btn {
          background: transparent; border: 1px solid ${LINE_BOLD};
          color: ${INK_SOFT}; padding: 14px 24px; cursor: pointer;
          font-family: 'DM Sans', sans-serif; font-size: 11px;
          letter-spacing: 2.5px; transition: all 0.25s; width: 100%;
          font-weight: 600; text-transform: uppercase;
        }
        .ghost-btn:hover { border-color: ${INK}; color: ${INK}; }

        .mode-pill {
          flex: 1; padding: 14px 8px; background: transparent;
          border: 1px solid ${LINE}; color: ${INK_FAINT};
          font-family: 'DM Sans', sans-serif; font-size: 11px;
          letter-spacing: 2.5px; cursor: pointer; transition: all 0.25s;
          font-weight: 600; text-transform: uppercase;
        }
        .mode-pill.active { background: ${COLORS.cream}; border-color: ${COLORS.cream}; color: ${COLORS.racingGreen}; }
        .mode-pill:hover:not(.active) { border-color: ${LINE_BOLD}; color: ${INK_SOFT}; }

        .tab-btn {
          background: none; border: none; border-bottom: 1px solid transparent;
          color: ${INK_FAINT}; font-family: 'DM Sans', sans-serif;
          font-size: 10px; letter-spacing: 2.5px; cursor: pointer;
          padding: 14px 0; margin-right: 24px; transition: all 0.2s;
          font-weight: 700; text-transform: uppercase;
        }
        .tab-btn.active { color: ${INK}; border-bottom-color: ${ACCENT}; }

        textarea, input[type="email"] {
          width: 100%; background: ${SURFACE}; border: 1px solid ${LINE};
          color: ${INK}; font-family: 'DM Sans', sans-serif; font-size: 13px;
          line-height: 1.85; padding: 18px; resize: none; outline: none;
          transition: border-color 0.25s; backdrop-filter: blur(4px);
        }
        textarea { min-height: 130px; font-size: 12.5px; }
        input[type="email"] { font-family: 'DM Sans', sans-serif; font-size: 15px; line-height: 1.4; padding: 16px 18px; }
        textarea:focus, input[type="email"]:focus { border-color: ${COLORS.cream}; }
        textarea::placeholder, input::placeholder { color: ${INK_FAINT}; }

        .upload-zone {
          border: 1px dashed ${LINE_BOLD}; background: ${SURFACE};
          display: flex; flex-direction: column; align-items: center;
          justify-content: center; padding: 56px 24px; cursor: pointer;
          gap: 16px; transition: all 0.3s; backdrop-filter: blur(4px);
        }
        .upload-zone:hover { border-color: ${COLORS.cream}; background: rgba(244,239,224,0.1); }

        .meter-row {
          display: flex; justify-content: space-between; align-items: baseline;
          padding: 12px 0; border-bottom: 1px solid ${LINE};
        }
        .meter-row:last-child { border-bottom: none; }
        .meter-label { font-family: 'DM Sans', sans-serif; font-size: 13px; color: ${INK_SOFT}; font-weight: 500; }
        .meter-value { font-family: 'DM Sans', sans-serif; font-size: 11px; letter-spacing: 2px; font-weight: 700; text-transform: uppercase; }

        .group-label {
          font-family: 'DM Sans', sans-serif; font-size: 10px;
          letter-spacing: 3px; color: ${INK_FAINT};
          margin-bottom: 8px; padding-bottom: 8px;
          border-bottom: 1px solid ${LINE};
          font-weight: 700; text-transform: uppercase;
        }

        .small-label {
          font-family: 'DM Sans', sans-serif; font-size: 10px;
          letter-spacing: 3px; color: ${INK_FAINT};
          font-weight: 700; text-transform: uppercase;
        }

        @keyframes appear { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        .reveal { animation: appear 0.7s cubic-bezier(0.2,0.8,0.3,1) forwards; }
        .reveal-1 { animation-delay: 0.05s; opacity: 0; }
        .reveal-2 { animation-delay: 0.18s; opacity: 0; }
        .reveal-3 { animation-delay: 0.32s; opacity: 0; }
        .reveal-4 { animation-delay: 0.48s; opacity: 0; }

        @keyframes pulse { 0%,100% { opacity: 0.25; } 50% { opacity: 1; } }
        .dot { display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: ${COLORS.brick}; animation: pulse 1.4s ease infinite; }
        .dot:nth-child(2) { animation-delay: 0.2s; }
        .dot:nth-child(3) { animation-delay: 0.4s; }

        .theme-toggle {
          position: absolute; top: 24px; right: 24px; z-index: 10;
          background: rgba(0,0,0,0.25); border: 1px solid ${LINE_BOLD};
          color: ${INK_SOFT}; width: 38px; height: 38px;
          cursor: pointer; font-family: 'DM Sans', sans-serif;
          font-size: 14px; display: flex; align-items: center; justify-content: center;
          transition: all 0.25s; backdrop-filter: blur(8px);
        }
        .theme-toggle:hover { border-color: ${COLORS.brick}; color: ${COLORS.brick}; }

        ::selection { background: ${COLORS.brick}; color: ${COLORS.cream}; }
      `}</style>

      {/* ─── Background Photography ─── */}
      <div style={{
        position: "fixed",
        inset: 0,
        backgroundImage: `url(${BG_IMAGE})`,
        backgroundSize: "cover",
        backgroundPosition: "center",
        backgroundRepeat: "no-repeat",
        zIndex: 0,
        filter: isNavy ? "hue-rotate(200deg) saturate(0.8) brightness(0.7)" : "saturate(1.15) brightness(0.95) contrast(1.05)",
        transition: "filter 0.5s ease",
      }} />

      {/* Tonal overlay — softer wash so image is clearly visible */}
      <div style={{
        position: "fixed",
        inset: 0,
        background: `linear-gradient(180deg, ${BG}99 0%, ${BG}77 40%, ${BG}99 100%)`,
        zIndex: 1,
        pointerEvents: "none",
        transition: "background 0.5s ease",
      }} />

      {/* Subtle diagonal accent line */}
      <div style={{
        position: "fixed",
        top: 0, left: "60%", right: 0, bottom: 0,
        background: `linear-gradient(135deg, transparent 49.7%, ${COLORS.brick}15 49.8%, ${COLORS.brick}15 50.2%, transparent 50.3%)`,
        pointerEvents: "none",
        zIndex: 2,
      }} />

      {/* Theme toggle */}
      <button className="theme-toggle" onClick={() => setTheme(isNavy ? "green" : "navy")} aria-label="Toggle theme">
        {isNavy ? "◐" : "◑"}
      </button>

      <div style={{ maxWidth: 620, margin: "0 auto", padding: "0 24px 80px", position: "relative", zIndex: 3 }}>

        {/* ═══════════ SCAN STAGE ═══════════ */}
        {stage === "scan" && (
          <>
            {/* Wordmark */}
            <div className={mounted ? "reveal reveal-1" : ""} style={{ padding: "56px 0 32px" }}>
              <Wordmark size="lg" />
              <div style={{ marginTop: 12 }}>
                <div className="small-label" style={{ fontSize: 11, letterSpacing: 4 }}>
                  Product Reality Check &nbsp;·&nbsp; Est. 2026
                </div>
              </div>
            </div>

            {/* Hero */}
            <div className={mounted ? "reveal reveal-2" : ""} style={{ marginBottom: 44 }}>
              <h1 style={{
                fontFamily: "'Libre Caslon Display', serif",
                fontSize: "clamp(42px, 9vw, 68px)",
                fontWeight: 400, lineHeight: 1.05,
                color: INK, marginBottom: 22,
                letterSpacing: "-0.02em",
              }}>
                Reads the back of<br />
                <span style={{
                  fontFamily: "'Italianno', cursive",
                  fontSize: "1.2em",
                  color: ACCENT_2,
                  fontWeight: 400,
                  letterSpacing: "0",
                  lineHeight: 0.85,
                }}>the bottle</span><br />
                so you don't have to.
              </h1>
              <p style={{ color: INK_SOFT, fontSize: 15, lineHeight: 1.75, fontWeight: 400, maxWidth: 480 }}>
                Photograph your label or paste the ingredient list. We decode the formulation, call out the marketing drama, and tell you what's actually inside — in language that respects your intelligence.
              </p>
            </div>

            {/* Mode + input */}
            <div className={mounted ? "reveal reveal-3" : ""}>
              <div style={{ display: "flex", gap: 0, marginBottom: 16 }}>
                <button className={`mode-pill ${mode === "photo" ? "active" : ""}`} onClick={() => { setMode("photo"); setError(""); }}>
                  Scan · Photo
                </button>
                <button className={`mode-pill ${mode === "text" ? "active" : ""}`} onClick={() => { setMode("text"); setError(""); }} style={{ borderLeft: "none" }}>
                  Paste · List
                </button>
              </div>

              {mode === "photo" && !image && (
                <div className="upload-zone" onClick={() => fileInputRef.current?.click()}>
                  <div style={{
                    fontFamily: "'Italianno', cursive",
                    fontSize: 64, fontWeight: 400, color: ACCENT,
                    lineHeight: 0.7,
                  }}>+</div>
                  <div style={{
                    fontFamily: "'Libre Caslon Display', serif",
                    fontSize: 22, color: INK, fontWeight: 400,
                  }}>
                    Capture the label
                  </div>
                  <div className="small-label" style={{ fontSize: 9, textAlign: "center", lineHeight: 1.9 }}>
                    Tap to open camera &nbsp;·&nbsp; or choose from gallery<br />
                    <span style={{ opacity: 0.7 }}>Bright light · close frame · ingredients in focus</span>
                  </div>
                </div>
              )}

              {mode === "photo" && image && (
                <div style={{ position: "relative" }}>
                  <img src={image.previewUrl} alt="Product label"
                    style={{ width: "100%", maxHeight: 280, objectFit: "cover", border: `1px solid ${LINE_BOLD}`, display: "block" }} />
                  <button onClick={() => setImage(null)} style={{
                    position: "absolute", top: 12, right: 12,
                    background: BG_DEEP, border: `1px solid ${LINE_BOLD}`,
                    color: INK, width: 32, height: 32, cursor: "pointer", fontSize: 14,
                  }}>✕</button>
                  <div style={{ padding: "12px 16px", background: SURFACE_SOLID, border: `1px solid ${LINE}`, borderTop: "none" }}>
                    <div className="small-label" style={{ fontSize: 9, color: ACCENT_2 }}>
                      Label captured &nbsp;·&nbsp; ready to analyse
                    </div>
                  </div>
                </div>
              )}

              {mode === "text" && (
                <div>
                  <div className="small-label" style={{ fontSize: 9, marginBottom: 8 }}>
                    Ingredient list
                  </div>
                  <textarea value={ingredients} onChange={e => setIngredients(e.target.value)}
                    placeholder="Aqua, Glycerin, Niacinamide, Rosa Damascena Flower Water, Dimethicone, Sodium Lauryl Sulfate, Parfum, Methylparaben..." />
                </div>
              )}

              <input ref={fileInputRef} type="file" accept="image/*" capture="environment" style={{ display: "none" }} onChange={handleImageUpload} />

              {error && (
                <div style={{ marginTop: 14, padding: "14px 16px", background: `${COLORS.brick}25`, border: `1px solid ${COLORS.brick}`, color: COLORS.cream, fontSize: 12, lineHeight: 1.7, fontFamily: "'DM Sans', sans-serif" }}>
                  {error}
                </div>
              )}

              <button className="serai-btn" style={{ marginTop: 16 }} onClick={startAnalysis} disabled={mode === "photo" ? !image : !ingredients.trim()}>
                Run the Scan
              </button>
            </div>

            {/* Footer */}
            <div className={mounted ? "reveal reveal-4" : ""} style={{ marginTop: 80, borderTop: `1px solid ${LINE}`, paddingTop: 22, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div style={{ fontFamily: "'Libre Caslon Display', serif", fontSize: 14, color: INK_FAINT, fontStyle: "italic" }}>
                A free tool from Serai.
              </div>
              <div className="small-label" style={{ fontSize: 9, letterSpacing: 3 }}>
                S/S · 2026
              </div>
            </div>
          </>
        )}

        {/* ═══════════ EMAIL GATE ═══════════ */}
        {stage === "gate" && (
          <div className="reveal reveal-1" style={{ padding: "80px 0 0" }}>
            <div style={{ marginBottom: 28 }}>
              <Wordmark size="md" />
            </div>

            <div style={{ background: SURFACE_SOLID, border: `1px solid ${LINE}`, padding: "44px 32px", backdropFilter: "blur(8px)" }}>
              <div className="small-label" style={{ fontSize: 10, color: ACCENT, marginBottom: 18 }}>
                One step away
              </div>
              <h2 style={{ fontFamily: "'Libre Caslon Display', serif", fontSize: 38, fontWeight: 400, lineHeight: 1.1, color: INK, marginBottom: 14, letterSpacing: "-0.02em" }}>
                Get the <span style={{ fontFamily: "'Italianno', cursive", fontSize: "1.3em", color: ACCENT_2, lineHeight: 0.8 }}>full</span> report.
              </h2>
              <p style={{ color: INK_SOFT, fontSize: 14, lineHeight: 1.75, marginBottom: 28 }}>
                Drop your email and we'll send the breakdown plus the occasional note on ingredients worth knowing. No spam.
              </p>

              <input type="email" value={email} onChange={e => { setEmail(e.target.value); setEmailError(""); }}
                placeholder="your@email.com" />
              {emailError && (
                <div style={{ color: COLORS.brick, fontSize: 11, marginTop: 10, fontFamily: "'DM Sans', sans-serif", fontWeight: 600 }}>
                  {emailError}
                </div>
              )}

              <button className="serai-btn" style={{ marginTop: 20 }} onClick={submitEmail}>
                Send Me the Report
              </button>
              <button className="ghost-btn" style={{ marginTop: 8 }} onClick={skipEmail}>
                Skip · Just Show It
              </button>
            </div>

            <div style={{ textAlign: "center", marginTop: 22, fontFamily: "'Libre Caslon Display', serif", fontSize: 13, color: INK_FAINT, fontStyle: "italic" }}>
              Your email never leaves Serai.
            </div>
          </div>
        )}

        {/* ═══════════ LOADING ═══════════ */}
        {loading && (
          <div style={{ position: "fixed", inset: 0, background: BG, display: "flex", alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 28, zIndex: 100 }}>
            <div style={{ fontFamily: "'Libre Caslon Display', serif", fontSize: 32, fontWeight: 400, color: INK, letterSpacing: "-0.02em" }}>
              {loadingMsg}
              <span style={{ fontFamily: "'Italianno', cursive", fontSize: 38, color: ACCENT, marginLeft: 6 }}>…</span>
            </div>
            <div style={{ display: "flex", gap: 10 }}>
              <span className="dot" /><span className="dot" /><span className="dot" />
            </div>
            <div className="small-label" style={{ fontSize: 10, letterSpacing: 5 }}>
              S E R A I &nbsp;·&nbsp; S C A N N E R
            </div>
          </div>
        )}

        {/* ═══════════ RESULT ═══════════ */}
        {stage === "result" && result && (
          <div style={{ paddingTop: 32 }}>

            <div className="reveal reveal-1" style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 36 }}>
              <Wordmark size="sm" />
              <div className="small-label" style={{ fontSize: 9 }}>
                Report · {new Date().toISOString().slice(0,10)}
              </div>
            </div>

            {/* Primary Result Card */}
            <div className="reveal reveal-2" style={{
              background: SURFACE_SOLID,
              border: `1px solid ${LINE_BOLD}`,
              padding: "44px 36px",
              marginBottom: 12,
              position: "relative",
              backdropFilter: "blur(8px)",
            }}>
              <div className="small-label" style={{
                position: "absolute", top: 24, right: 32, fontSize: 9,
              }}>
                Reality Score
              </div>

              <div style={{
                fontFamily: "'Libre Caslon Display', serif",
                fontSize: 130, fontWeight: 400,
                lineHeight: 0.85, color: INK,
                marginTop: 18, marginBottom: 8,
                letterSpacing: "-0.05em",
              }}>
                {result.score}
                <span style={{
                  fontFamily: "'Italianno', cursive",
                  fontSize: 56, color: ACCENT, fontWeight: 400,
                  marginLeft: 8, letterSpacing: 0,
                }}> /10</span>
              </div>

              <div style={{ width: 64, height: 2, background: ACCENT, margin: "32px 0 26px" }} />

              <div style={{
                display: "inline-block",
                padding: "10px 22px",
                background: tagMeta.tier === "low" ? COLORS.brick : "transparent",
                border: `1px solid ${tagMeta.tier === "low" ? COLORS.brick : tagColor}`,
                color: tagMeta.tier === "low" ? COLORS.cream : tagColor,
                fontFamily: "'DM Sans', sans-serif",
                fontSize: 11, letterSpacing: 3.5, fontWeight: 700,
                marginBottom: 28, textTransform: "uppercase",
              }}>
                {result.statusTag}
              </div>

              <div style={{
                fontFamily: "'Libre Caslon Display', serif",
                fontSize: 30, fontWeight: 400,
                lineHeight: 1.3, color: INK,
                fontStyle: "italic",
                letterSpacing: "-0.02em",
                marginBottom: 30,
              }}>
                "{result.punchline}"
              </div>

              <div style={{ display: "flex", alignItems: "center", gap: 16, paddingTop: 24, borderTop: `1px solid ${LINE}` }}>
                <div className="small-label" style={{ fontSize: 9 }}>
                  Verdict
                </div>
                <div style={{
                  fontFamily: "'DM Sans', sans-serif",
                  fontSize: 13, letterSpacing: 3, color: keepColor, fontWeight: 700,
                  textTransform: "uppercase",
                }}>
                  → {result.keepSkip}
                </div>
              </div>
            </div>

            <div style={{ textAlign: "right", marginBottom: 36, fontFamily: "'Libre Caslon Display', serif", fontSize: 13, color: INK_FAINT, fontStyle: "italic" }}>
              An S/S report.
            </div>

            {result.extractedIngredients && (
              <div className="reveal reveal-3" style={{ background: SURFACE_SOLID, border: `1px solid ${LINE}`, padding: "16px 20px", marginBottom: 28, backdropFilter: "blur(8px)" }}>
                <div className="small-label" style={{ fontSize: 9, marginBottom: 8 }}>
                  Read from your photo
                </div>
                <div style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 12, color: INK_SOFT, lineHeight: 1.85 }}>
                  {result.extractedIngredients}
                </div>
              </div>
            )}

            <div className="reveal reveal-3" style={{ borderBottom: `1px solid ${LINE}`, marginBottom: 24, display: "flex", overflowX: "auto" }}>
              {[
                ["breakdown", "Breakdown"],
                ["flags", `Flags (${result.redFlags?.length || 0})`],
                ["clean", "Clean"],
                ["verdict", "Bottom Line"],
              ].map(([id, label]) => (
                <button key={id} className={`tab-btn ${activeTab === id ? "active" : ""}`} onClick={() => setActiveTab(id)}>
                  {label}
                </button>
              ))}
            </div>

            {/* BREAKDOWN */}
            {activeTab === "breakdown" && result.meters && (
              <div className="reveal reveal-4">
                <div style={{ marginBottom: 32 }}>
                  <div className="group-label">Skin Safety</div>
                  {[
                    ["Barrier Stress", result.meters.skinSafety?.barrierStress, "barrierStress"],
                    ["Irritation Risk", result.meters.skinSafety?.irritationRisk, "irritationRisk"],
                    ["Acne Trigger", result.meters.skinSafety?.acneTrigger, "acneTrigger"],
                    ["Actives Balance", result.meters.skinSafety?.activesBalance, "activesBalance"],
                  ].map(([label, value, key]) => (
                    <div key={key} className="meter-row">
                      <span className="meter-label">{label}</span>
                      <span className="meter-value" style={{ color: isRiskHigh(key, value) ? ACCENT : INK }}>
                        {value}
                      </span>
                    </div>
                  ))}
                </div>

                <div style={{ marginBottom: 32 }}>
                  <div className="group-label">Honesty</div>
                  <div className="meter-row">
                    <span className="meter-label">Botanical Reality</span>
                    <span className="meter-value" style={{ color: INK }}>{result.meters.honesty?.botanicalReality}</span>
                  </div>
                  {[
                    ["Marketing vs Formula", result.meters.honesty?.marketingVsFormula, "marketingVsFormula"],
                    ["Fragrance Load", result.meters.honesty?.fragranceLoad, "fragranceLoad"],
                  ].map(([label, value, key]) => (
                    <div key={key} className="meter-row">
                      <span className="meter-label">{label}</span>
                      <span className="meter-value" style={{ color: isRiskHigh(key, value) ? ACCENT : INK }}>
                        {value}
                      </span>
                    </div>
                  ))}
                </div>

                <div>
                  <div className="group-label">Practical</div>
                  <div className="meter-row">
                    <span className="meter-label">Humidity Compatibility</span>
                    <span className="meter-value" style={{ color: result.meters.practical?.humidityCompatibility === "NO" ? ACCENT : INK }}>
                      {result.meters.practical?.humidityCompatibility}
                    </span>
                  </div>
                  <div className="meter-row">
                    <span className="meter-label">Melanin Match</span>
                    <span className="meter-value" style={{ color: ["CAUTION","AVOID"].includes(result.meters.practical?.melaninMatch) ? ACCENT : INK }}>
                      {result.meters.practical?.melaninMatch}
                    </span>
                  </div>
                  <div className="meter-row">
                    <span className="meter-label">Value vs Pricing</span>
                    <span className="meter-value" style={{ color: result.meters.practical?.valueVsPricing === "LOW" ? ACCENT : INK }}>
                      {result.meters.practical?.valueVsPricing}
                    </span>
                  </div>
                </div>
              </div>
            )}

            {/* FLAGS */}
            {activeTab === "flags" && (
              <div className="reveal reveal-4">
                {!result.redFlags?.length ? (
                  <div style={{ textAlign: "center", padding: "56px 0" }}>
                    <div style={{ fontFamily: "'Italianno', cursive", fontSize: 64, color: ACCENT_2, marginBottom: 8, lineHeight: 1 }}>—</div>
                    <div className="small-label" style={{ fontSize: 10, marginBottom: 10 }}>No Flags</div>
                    <div style={{ fontFamily: "'Libre Caslon Display', serif", fontSize: 20, color: INK_SOFT, fontStyle: "italic" }}>This one's clean.</div>
                  </div>
                ) : result.redFlags.map((flag, i) => (
                  <div key={i} style={{ background: SURFACE_SOLID, border: `1px solid ${LINE}`, padding: "24px 26px", marginBottom: 12, borderLeft: `3px solid ${ACCENT}`, backdropFilter: "blur(8px)" }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 14 }}>
                      <div style={{ fontFamily: "'Libre Caslon Display', serif", fontSize: 20, fontWeight: 400, color: INK, lineHeight: 1.3 }}>
                        {flag.ingredient}
                      </div>
                      <div className="small-label" style={{ fontSize: 9, color: ACCENT, letterSpacing: 2 }}>
                        Flag
                      </div>
                    </div>
                    <div style={{ fontSize: 13, color: INK_SOFT, lineHeight: 1.7 }}>
                      {flag.concern}
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* CLEAN */}
            {activeTab === "clean" && (
              <div className="reveal reveal-4">
                {result.cleanIngredients?.length ? (
                  <>
                    <div style={{ fontFamily: "'Libre Caslon Display', serif", fontSize: 20, color: INK_SOFT, lineHeight: 1.7, marginBottom: 24, fontStyle: "italic" }}>
                      The ones genuinely doing the work.
                    </div>
                    <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                      {result.cleanIngredients.map((ing, i) => (
                        <span key={i} style={{
                          background: SURFACE,
                          border: `1px solid ${LINE_BOLD}`,
                          color: INK,
                          padding: "9px 16px",
                          fontFamily: "'DM Sans', sans-serif",
                          fontSize: 11, letterSpacing: 0.5,
                          fontWeight: 500,
                          backdropFilter: "blur(4px)",
                        }}>
                          {ing}
                        </span>
                      ))}
                    </div>
                  </>
                ) : (
                  <div style={{ fontSize: 14, color: INK_FAINT, fontStyle: "italic", fontFamily: "'Libre Caslon Display', serif" }}>
                    No standout clean ingredients identified.
                  </div>
                )}
              </div>
            )}

            {/* BOTTOM LINE */}
            {activeTab === "verdict" && (
              <div className="reveal reveal-4" style={{ background: SURFACE_SOLID, border: `1px solid ${LINE_BOLD}`, padding: "36px 32px", borderLeft: `3px solid ${ACCENT_2}`, backdropFilter: "blur(8px)" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 22 }}>
                  <div style={{ flex: 1, height: 1, background: LINE }} />
                  <div className="small-label" style={{ fontSize: 9 }}>Friend to Friend</div>
                  <div style={{ flex: 1, height: 1, background: LINE }} />
                </div>
                <p style={{ fontFamily: "'Libre Caslon Display', serif", fontSize: 24, lineHeight: 1.55, color: INK, fontWeight: 400, letterSpacing: "-0.01em" }}>
                  {result.bottomLine}
                </p>
              </div>
            )}

            <div style={{ marginTop: 56, borderTop: `1px solid ${LINE}`, paddingTop: 32, display: "flex", flexDirection: "column", gap: 12 }}>
              <button className="serai-btn" onClick={reset}>
                Scan Another
              </button>
              <div style={{ textAlign: "center", marginTop: 12, fontFamily: "'Libre Caslon Display', serif", fontSize: 13, color: INK_FAINT, fontStyle: "italic" }}>
                Reads the back of the bottle so you don't have to.
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
